(async()=>{
 const wait=()=>new Promise(resolve=>setTimeout(resolve,200)),check=(value,message)=>{if(!value)throw Error(message)};
 const click=async text=>{const el=[...document.querySelectorAll('button')].find(el=>el.textContent.trim()===text);check(el,'Missing '+text);el.click();await wait()};
 location.hash='/governance/audit';await wait();
 const rows=()=>[...document.querySelectorAll('.resource-data-list tbody tr')].filter(row=>row.querySelector('.data-list-actions'));
 const expected=Array.from({length:501},(_,i)=>'audit-'+i).sort();
 check(rows().length===50,'Audit does not bound rendered rows');
 check(document.documentElement.scrollWidth<=innerWidth+1,'Long audit title overflows viewport');
 check(rows()[0].textContent.includes(expected[0]),'First page missing first stable ID');
 await click('下一页');check(rows().length===50 && rows()[0].textContent.includes(expected[50]),'Second page duplicates/skips first row');
 check(decodeURIComponent(location.hash).includes('audit:'),'Pagination URL missing');
 const input=document.querySelector('.data-list-tools input');
 const fill=async value=>{Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(input,value);input.dispatchEvent(new Event('input',{bubbles:true}));await wait()};
 const start=performance.now();await fill('audit-500');const searchMs=performance.now()-start;
 check(rows().length===1 && rows()[0].textContent.includes('audit-500'),'Search fails on ID or retains old page');
 await fill('evidence=123');check(rows().length===1 && rows()[0].textContent.includes('evidence=123'),'Search ignores target identity');
 const path=location.hash.split('?')[0]; await click('查看记录');
 const dialog=document.querySelector('dialog[open]');check(dialog,'Audit click did not open record details');
 check(location.hash.split('?')[0]===path,'Audit record navigated away');
 check(dialog.textContent.includes('audit-123') && dialog.textContent.includes('此记录未保存独立理由'),'Stored identity or missing reason not clear');
 const link=dialog.querySelector('a[target="_blank"]');check(link && link.rel.includes('noopener') && link.getAttribute('href').includes('evidence=123'),'Explicit new-tab evidence link missing');
 check(link.getAttribute('href').includes('tenant=')&&link.getAttribute('href').includes('scope=launch'),'Target link loses tenant/project');
 check(decodeURIComponent(location.hash).includes('audit.record'),'Selected audit record not URL-backed');
 const deepLink=location.hash; document.querySelector('dialog[open] [aria-label="关闭弹窗"]').click();await wait();check(!document.querySelector('dialog[open]'),'Close did not restore list');
 check(rows().length===1 && input.value==='evidence=123','Close lost original filter');
 location.hash=deepLink;await wait();check(document.querySelector('dialog[open]')?.textContent.includes('audit-123'),'Deep link does not restore record');document.querySelector('dialog[open] [aria-label="关闭弹窗"]').click();await wait();
 await click('导出当前查询结果');check(document.querySelector('.resource-data-list').textContent.includes('已生成当前查询结果 JSON：1 条记录'),'Audit query export failed');
 await fill('NO_MATCH_12345');check(!rows().length && document.querySelector('main').textContent.includes('当前条件下没有记录'),'Missing empty result feedback');
 await fill('');for(let page=1;page<11;page++)await click('下一页');
 check(rows().length===1 && rows()[0].textContent.includes(expected[500]),'Last page incomplete boundary wrong');
 const next=[...document.querySelectorAll('button')].find(el=>el.textContent.trim()==='下一页');check(next.disabled,'Last-page next remains enabled');
 const ths=[...document.querySelectorAll('.resource-data-list th')];check(getComputedStyle(ths[0]).position==='sticky'&&getComputedStyle(ths.at(-1)).position==='sticky','Fixed header/operation columns missing');
 await click('刷新');check(document.querySelector('.resource-data-list').textContent.includes('最近成功：')&&!document.querySelector('.resource-data-list').textContent.includes('最近成功：尚未刷新'),'Refresh has no success result');
 return {pass:true,width:innerWidth,records:501,maxRendered:50,searchMs,checks:['bounded DOM','long text','stable paging boundaries','ID and target search','empty result','search resets page','in-place actual audit detail','deep-linked selected record','tenant/project preserved new-tab link','query export','sticky columns','local refresh']};
})()
